import { Page, Locator } from '@playwright/test'

export class BasePage {
  constructor(protected page: Page) {}

  async navigateTo(path: string) {
    await this.page.goto(path)
  }

  async waitForLoad() {
    await this.page.waitForLoadState('networkidle')
  }

  async waitForNavigation() {
    await this.page.waitForLoadState('domcontentloaded')
  }

  async clickNavItem(name: string) {
    await this.page.locator(`nav`).getByText(name).click()
  }

  async getToastMessage(): Promise<string | null> {
    const toast = this.page.locator('[data-sonner-toast]').first()
    if (await toast.isVisible()) {
      return toast.textContent()
    }
    return null
  }

  async waitForToast(text: string) {
    await this.page.locator('[data-sonner-toast]').filter({ hasText: text }).waitFor()
  }

  async dismissToast() {
    const toast = this.page.locator('[data-sonner-toast]').first()
    if (await toast.isVisible()) {
      await toast.locator('button').click()
    }
  }
}

import { test, expect } from '@playwright/test'
import { LoginPage } from '../../pages'
import { TEST_USERS, logout } from '../../helpers'

test.describe('Login', () => {
  let loginPage: LoginPage

  test.beforeEach(async ({ page }) => {
    loginPage = new LoginPage(page)
    await loginPage.goto()
  })

  test('should display login form', async ({ page }) => {
    await expect(loginPage.emailInput).toBeVisible()
    await expect(loginPage.passwordInput).toBeVisible()
    await expect(loginPage.submitButton).toBeVisible()
  })

  test('should login successfully with valid credentials', async ({ page }) => {
    await loginPage.login(TEST_USERS.admin.email, TEST_USERS.admin.password)
    await loginPage.expectLoginSuccess()
  })

  test('should show error with invalid credentials', async ({ page }) => {
    await loginPage.login('invalid@test.com', 'wrongpassword')
    await loginPage.expectLoginError()
  })

  test('should show validation error for empty email', async ({ page }) => {
    await loginPage.passwordInput.fill('password')
    await loginPage.submitButton.click()
    // Should stay on login page
    await expect(page).toHaveURL(/\/login/)
  })

  test('should show validation error for empty password', async ({ page }) => {
    await loginPage.emailInput.fill('test@test.com')
    await loginPage.submitButton.click()
    // Should stay on login page
    await expect(page).toHaveURL(/\/login/)
  })

  test('should navigate to register page', async ({ page }) => {
    await loginPage.goToRegister()
    await expect(page).toHaveURL(/\/register/)
  })

  test('should logout successfully', async ({ page }) => {
    // First login
    await loginPage.login(TEST_USERS.admin.email, TEST_USERS.admin.password)
    await loginPage.expectLoginSuccess()

    // Then logout
    await logout(page)
    await expect(page).toHaveURL(/\/login/)
  })
})

test.describe('Authentication Redirect', () => {
  test('should redirect to login when accessing protected route', async ({ page }) => {
    await page.goto('/settings/users')
    await expect(page).toHaveURL(/\/login/)
  })

  test('should redirect to dashboard after login', async ({ page }) => {
    const loginPage = new LoginPage(page)
    await loginPage.goto()
    await loginPage.login(TEST_USERS.admin.email, TEST_USERS.admin.password)
    // Should be on dashboard or chat
    await expect(page).toHaveURL(/\/(dashboard|chat)?/)
  })
})

